class Solution {
public:
    string minimizeStringValue(string s) {
        vector<int> cnt(26, 0);
        int q = 0;
        for (char c : s) {
            if (c == '?') q++;
            else cnt[c - 'a']++;
        }
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        for (int i = 0; i < 26; ++i) pq.push({cnt[i], i});
        vector<char> picks;
        for (int i = 0; i < q; ++i) {
            auto [freq, ch] = pq.top(); pq.pop();
            picks.push_back('a' + ch);
            pq.push({freq + 1, ch});
        }
        sort(picks.begin(), picks.end());
        int p = 0;
        for (char& c : s) {
            if (c == '?') c = picks[p++];
        }
        return s;
    }
};

class Solution {
    public String minimizeStringValue(String s) {
        int[] cnt = new int[26];
        int q = 0;
        for (char c : s.toCharArray()) {
            if (c == '?') q++;
            else cnt[c - 'a']++;
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        for (int i = 0; i < 26; i++) pq.offer(new int[]{cnt[i], i});
        char[] picks = new char[q];
        for (int i = 0; i < q; i++) {
            int[] top = pq.poll();
            picks[i] = (char)('a' + top[1]);
            pq.offer(new int[]{top[0] + 1, top[1]});
        }
        Arrays.sort(picks);
        char[] chars = s.toCharArray();
        int p = 0;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '?') chars[i] = picks[p++];
        }
        return new String(chars);
    }
}

var minimizeStringValue = function(s) {
    const cnt = new Array(26).fill(0);
    let q = 0;
    for (const c of s) {
        if (c === '?') q++;
        else cnt[c.charCodeAt(0) - 97]++;
    }
    const picks = [];
    for (let k = 0; k < q; ++k) {
        let minFreq = Infinity, bestCh = 0;
        for (let i = 0; i < 26; ++i) {
            if (cnt[i] < minFreq) {
                minFreq = cnt[i];
                bestCh = i;
            }
        }
        picks.push(String.fromCharCode(97 + bestCh));
        cnt[bestCh]++;
    }
    picks.sort();
    const chars = s.split('');
    let p = 0;
    for (let i = 0; i < chars.length; ++i) {
        if (chars[i] === '?') chars[i] = picks[p++];
    }
    return chars.join('');
};
